    "horizontal optical axis (black line)",
    "biconvex converging lens (pale blue, semi-transparent oval)",
    "vertical dashed line through the center of the lens",
    "object (red upward-pointing arrow on the left)",
    "image (red downward-pointing arrow on the right)",
    "near focal point (red dot on left axis) labeled F",
    "far focal point (red dot on right axis) labeled F",
    "Ray 1 (red path: object tip -> parallel to axis -> lens -> far F -> image tip), with arrowheads and label '1'",
    "Ray 2 (green path: object tip -> straight through lens center -> image tip), with arrowheads and label '2'",
    "Ray 3 (purple path: object tip -> near F -> lens -> parallel to axis -> image tip), with arrowheads and label '3'",
    "measurement bracket and label for object height (h_o) to the left of the object",
    "measurement bracket and label for image height (h_i) to the right of the image",
    "measurement bracket and label for focal length (f) from lens center to far F",
    "measurement bracket and label for object distance (d_o) below the left axis",
    "measurement bracket and label for image distance (d_i) below the right axis"
  ],
  "interactions": [
    {
      "id": "objectDistance",
      "type": "slider",
      "label": "Object distance (d_o)",
      "range": [1.2, 3.5, 0.1],
      "default": 2.5,
      "teaches": "Dragging the object changes its distance (d_o), which inversely affects the image distance (d_i) and dynamically alters the image magnification, visualizing the thin-lens equation."
    },
    {
      "id": "highlightRay",
      "type": "click",
      "teaches": "Clicking a principal ray isolates its specific geometric rule—parallel to focal (1), straight through center (2), or focal to parallel (3)—showing that any two rays are sufficient to pinpoint the image."
    },
    {
      "id": "measurementsToggle",
      "type": "toggle",
      "label": "Annotations",
      "options": ["Rays Only", "Show Measurements"],
      "default": "Show Measurements",
      "teaches": "Toggling the measurement overlays maps the physical drawing onto the abstract variables (d_o, d_i, h_o, h_i, f) used in algebraic optics formulas."
    }
  ],
  "demo_steps": [
    {
      "title": "Three Principal Rays",
      "narration": "To find where a lens forms an image, we trace three principal rays from the top of the object. Click any ray to highlight its specific path. They all converge at a single point to locate the image tip.",
