// @FIGURE_CODE_BEGIN
const W = 880, H = 780;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Scale & Constants
const S = 75;            // pixels per unit
const cx = 350, cy = 320; // lens center
const f = 1.0;           // focal length
const ho = 1.0;          // object height

// State
let currentDo = 2.5;
let currentHighlight = 'all';
let showMeasurements = false;

// Theme Colors
const colorRay1 = '#d62728';
const colorRay2 = '#2ca02c';
const colorRay3 = '#9467bd';
const colorObj = '#cc2222';
const colorExt = '#999';

// Layers
const layerGrid = draw.group();
const layerAnnos = draw.group();
const layerLens = draw.group();
const layerRays = draw.group();
const layerObjects = draw.group();
const layerTopAnnos = draw.group();

// Static Background Elements
layerGrid.line(0, cy, W, cy).stroke({ color: '#222', width: 1.2 });
layerLens.line(cx, 60, cx, 750).stroke({ color: '#555', width: 1.2, dasharray: '6,4' });

const lensH = 200;
const lensW = 22;
layerLens.path(`M ${cx} ${cy - lensH} Q ${cx + lensW} ${cy} ${cx} ${cy + lensH} Q ${cx - lensW} ${cy} ${cx} ${cy - lensH}`)
  .fill({ color: '#cbe6f9', opacity: 0.85 })
  .stroke({ color: '#5a9bd4', width: 1.5 });

const fpSize = 4.5;
layerLens.circle(fpSize*2).center(cx - f*S, cy).fill(colorObj);
layerTopAnnos.text('F').font({ size: 16, style: 'italic', family: 'serif' }).center(cx - f*S, cy + 18);
layerTopAnnos.circle(24).center(cx - f*S, cy).fill('transparent').css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Near focal point (F)', e)).on('mouseleave', hideTooltip);

layerLens.circle(fpSize*2).center(cx + f*S, cy).fill(colorObj);
layerTopAnnos.text('F').font({ size: 16, style: 'italic', family: 'serif' }).center(cx + f*S, cy + 18);
layerTopAnnos.circle(24).center(cx + f*S, cy).fill('transparent').css('cursor', 'pointer')
  .on('mousemove', e => showTooltip('Far focal point (F)', e)).on('mouseleave', hideTooltip);

// Dynamic Groups
const r1g = layerRays.group();
const r2g = layerRays.group();
const r3g = layerRays.group();
const objGroup = layerObjects.group();
const imgGroup = layerObjects.group();
const annosGroup = layerAnnos.group();

// Helpers
function drawThickArrow(g, x1, y1, x2, y2, color, w, tip) {
  const headL = 16, headW = 12;
  const dirY = y2 > y1 ? 1 : -1;
  const gArrow = g.group().css('cursor', 'pointer')
    .on('mousemove', e => showTooltip(tip, e))
    .on('mouseleave', hideTooltip);

  gArrow.line(x1, y1, x2, y2 - dirY*headL).stroke({ color, width: w });
  gArrow.polygon(`${x2 - headW/2},${y2 - dirY*headL} ${x2 + headW/2},${y2 - dirY*headL} ${x2},${y2}`).fill(color);
  gArrow.rect(24, Math.abs(y2 - y1) + headL).center(x1, (y1 + y2)/2).fill('transparent');
}

function drawDimension(g, x1, y1, x2, y2, text, isHoriz) {
  const tick = 8;
  if (isHoriz) {
     g.line(x1, y1-tick, x1, y1+tick).stroke({color: '#000', width: 1.5});
     g.line(x2, y2-tick, x2, y2+tick).stroke({color: '#000', width: 1.5});
     g.polygon('0,-3 10,0 0,3').fill('#000').center(x1 + 5, y1).rotate(180);
     g.polygon('0,-3 10,0 0,3').fill('#000').center(x2 - 5, y2);
  } else {
     g.line(x1-tick, y1, x1+tick, y1).stroke({color: '#000', width: 1.5});
     g.line(x2-tick, y2, x2+tick, y2).stroke({color: '#000', width: 1.5});
     g.polygon('0,-3 10,0 0,3').fill('#000').center(x1, y1 + 5).rotate(-90);
     g.polygon('0,-3 10,0 0,3').fill('#000').center(x2, y2 - 5).rotate(90);
  }
  g.line(x1, y1, x2, y2).stroke({color: '#000', width: 1});

  const midX = (x1 + x2)/2, midY = (y1 + y2)/2;
  const tGroup = g.group();
  const bg = tGroup.rect().fill('#fff');

  const t = tGroup.text(add => {
    const parts = text.split('_');
    add.tspan(parts[0]);
    if(parts[1]) add.tspan(parts[1]).dy(5).font({size: 11});
  }).font({ family: 'serif', size: 16, style: 'italic' });

  t.center(midX, midY);
  bg.size(t.bbox().w + 10, t.bbox().h + 4).center(midX, midY);
  t.front();
}

function drawRay(g, pts, color, opacity, labelStr, rayId, tip, labelPos) {
  g.polyline(pts).fill('none').stroke({ color, width: 2, opacity });

  g.polyline(pts).fill('none').stroke({ color: 'transparent', width: 20 })
    .css('cursor', 'pointer')
    .on('mousemove', e => showTooltip(tip, e))
    .on('mouseleave', hideTooltip)
    .on('click', () => {
       document.querySelector(`input[name="ray"][value="${rayId}"]`).checked = true;
       update_highlight(rayId);
    });

  function addArrow(p1, p2) {
    const mx = (p1[0] + p2[0]) / 2, my = (p1[1] + p2[1]) / 2;
    const angle = Math.atan2(p2[1] - p1[1], p2[0] - p1[0]) * 180 / Math.PI;
    g.polygon('0,-4.5 12,0 0,4.5').fill(color).opacity(opacity).center(mx, my).rotate(angle);
  }
  addArrow(pts[0], pts[1]);
  addArrow(pts[1], pts[2]);

  const bg = g.rect().fill('rgba(255,255,255,0.8)');
  const txt = g.text(labelStr).font({ family: 'sans-serif', size: 16, weight: 'bold' }).fill(color).opacity(opacity);
  txt.center(labelPos.x, labelPos.y);
  bg.size(txt.bbox().w + 6, txt.bbox().h + 2).center(labelPos.x, labelPos.y);
  txt.front();
}

// Math & Rendering
function updateScene() {
  r1g.clear(); r2g.clear(); r3g.clear();
  objGroup.clear(); imgGroup.clear(); annosGroup.clear();

  const di = 1 / (1/f - 1/currentDo);
  const m = -di / currentDo;
  const hi = m * ho;

  const objX = cx - currentDo * S, objY = cy - ho * S;
  const imgX = cx + di * S, imgY = cy - hi * S;

  const r1op = (currentHighlight === 'all' || currentHighlight === '1') ? 1 : 0.15;
  const r2op = (currentHighlight === 'all' || currentHighlight === '2') ? 1 : 0.15;
  const r3op = (currentHighlight === 'all' || currentHighlight === '3') ? 1 : 0.15;

  const extX = 140;
  const r1pts = [ [objX, objY], [cx, objY], [imgX, imgY], [imgX + extX, imgY + ((imgY - objY)/(imgX - cx)) * extX] ];
  const r2pts = [ [objX, objY], [cx, cy], [imgX, imgY], [imgX + extX, imgY + ((imgY - cy)/(imgX - cx)) * extX] ];
  const r3pts = [ [objX, objY], [cx, imgY], [imgX, imgY], [imgX + extX, imgY] ];

  drawRay(r1g, r1pts, colorRay1, r1op, '1', '1', "Ray 1: Travels parallel to the axis, then through far focal point.", { x: cx - currentDo*S/2, y: objY - 18 });
  drawRay(r2g, r2pts, colorRay2, r2op, '2', '2', "Ray 2: Passes straight through the lens center un-deflected.", { x: cx - currentDo*S/2 - 12, y: (objY + cy)/2 - 16 });
  drawRay(r3g, r3pts, colorRay3, r3op, '3', '3', "Ray 3: Passes through near focal point, then emerges parallel to axis.", { x: cx - currentDo*S/2 - 20, y: (objY + imgY)/2 + 16 });

  drawThickArrow(objGroup, objX, cy, objX, objY, colorObj, 4.5, "Object (height = h_o)");
  drawThickArrow(imgGroup, imgX, cy, imgX, imgY, '#e34242', 4.5, "Real Image (height = h_i)");

  if (showMeasurements) {
    annosGroup.line(objX - 45, cy, objX, cy).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    annosGroup.line(objX - 45, objY, objX, objY).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    drawDimension(annosGroup, objX - 35, cy, objX - 35, objY, 'h_o', false);

    annosGroup.line(imgX, cy, imgX + 45, cy).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    annosGroup.line(imgX, imgY, imgX + 45, imgY).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    drawDimension(annosGroup, imgX + 35, cy, imgX + 35, imgY, 'h_i', false);

    const dY = 730;
    annosGroup.line(objX, cy, objX, dY + 10).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    annosGroup.line(cx, cy + 220, cx, dY + 10).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    annosGroup.line(imgX, cy, imgX, dY + 10).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    drawDimension(annosGroup, objX, dY, cx, dY, 'd_o', true);
    drawDimension(annosGroup, cx, dY, imgX, dY, 'd_i', true);

    const fY = cy - 40;
    annosGroup.line(cx + f*S, cy, cx + f*S, fY - 10).stroke({ color: colorExt, width: 1, dasharray: '4,4' });
    drawDimension(annosGroup, cx, fY, cx + f*S, fY, 'f', true);
  }
}

// Handlers
window.update_objectDistance = function(val) { currentDo = val; updateScene(); };
window.update_highlight = function(val) { currentHighlight = val; updateScene(); };
window.toggle_measurements = function(val) { showMeasurements = val; updateScene(); };

// Demo Player
const demoSteps = [
  {
    title: "Three Principal Rays",
    narration: "To find where a lens forms an image, we trace three principal rays from the top of the object. Click any ray to highlight its specific path. They all converge at a single point to locate the image tip.",
    state: { do: 2.5, meas: false }
  },
  {
    title: "Defining the Variables",
    narration: "Turning on the measurements reveals the geometric variables. The distances from the lens to the object (d_o) and image (d_i), along with the focal length (f), are strictly linked by the thin-lens equation.",
    state: { do: 2.5, meas: true }
  },
  {
    title: "The Lens Equation in Action",
    narration: "Move the object closer to the focal point. The rays must travel further to converge, drastically increasing the image distance (d_i) and producing a larger, highly magnified image.",
    state: { do: 1.4, meas: true }
  }
];

let stepIdx = 0;
function applyStep(idx) {
  const s = demoSteps[idx];
  document.getElementById('demoNarration').innerHTML = `<strong>${s.title}:</strong> ${s.narration}`;
  document.getElementById('stepLabel').textContent = `${idx + 1} / ${demoSteps.length}`;

  document.getElementById('objectDistanceInput').value = s.state.do;
  document.getElementById('objectDistanceVal').value = s.state.do.toFixed(1);
  currentDo = s.state.do;

  document.getElementById('measurementsToggleInput').checked = s.state.meas;
  showMeasurements = s.state.meas;

  document.querySelector('input[name="ray"][value="all"]').checked = true;
  currentHighlight = 'all';

  document.getElementById('btnPrev').disabled = (idx === 0);
  document.getElementById('btnNext').disabled = (idx === demoSteps.length - 1);

  updateScene();
}
window.prevStep = function() { if(stepIdx > 0) applyStep(--stepIdx); };
window.nextStep = function() { if(stepIdx < demoSteps.length - 1) applyStep(++stepIdx); };

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
