      <input type="radio" name="ray" value="1" onchange="update_highlight('1')"> 
      <span style="color:#d1292e; font-weight: 600;">Ray 1 (Parallel)</span>
    </label>
    <label style="flex-direction: row; align-items: center; gap: 6px; cursor: pointer;">
      <input type="radio" name="ray" value="2" onchange="update_highlight('2')"> 
      <span style="color:#6b9e30; font-weight: 600;">Ray 2 (Center)</span>
    </label>
    <label style="flex-direction: row; align-items: center; gap: 6px; cursor: pointer;">
      <input type="radio" name="ray" value="3" onchange="update_highlight('3')"> 
      <span style="color:#714b9c; font-weight: 600;">Ray 3 (Focal)</span>
    </label>
  </div>
</div>

<div>
  <label style="flex-direction: row; align-items: center; gap: 6px; font-weight: 600; cursor: pointer;">
    <input id="measurementsToggleInput" type="checkbox" checked onchange="toggle_measurements(this.checked)"> 
    Show Measurements
